import{_ as a,a as e,b as i,c as o}from"./chunks/state-monitoring-4.Bpnw36H5.js";import{_ as r,o as n,c as s,a5 as l}from"./chunks/framework.CcrBcQWS.js";const _=JSON.parse('{"title":"5. 상태 모니터링","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/common/state-monitoring.md","filePath":"ko/guides/common/state-monitoring.md","lastUpdated":1787021357000}'),c={name:"ko/guides/common/state-monitoring.md"};function d(m,t,g,p,h,u){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-상태-모니터링" tabindex="-1">5. 상태 모니터링 <a class="header-anchor" href="#_5-상태-모니터링" aria-label="Permalink to &quot;5. 상태 모니터링&quot;">​</a></h1><p><strong>목표:</strong> RBQGUI의 실시간 상태 패널을 읽는 방법을 이해합니다.</p><p>RBQGUI의 상태 모니터링 화면에서는 비상 상태, 배터리 잔량, 센서 측정값, 모듈 상태를 한 화면에서 확인할 수 있습니다.</p><h2 id="상단-상태-표시줄" tabindex="-1">상단 상태 표시줄 <a class="header-anchor" href="#상단-상태-표시줄" aria-label="Permalink to &quot;상단 상태 표시줄&quot;">​</a></h2><p>상단 표시줄에는 <strong>EMERGENCY</strong> 상태 표시등, 배터리 전압, 연결 상태 및 기타 시스템 아이콘이 한눈에 보입니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="상단 상태 표시줄" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">상단 상태 표시줄 — EMERGENCY, 배터리, 연결 표시</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p><strong>EMERGENCY</strong> 표시등이 켜져 있으면 즉시 모든 작업을 중단하고 <a href="/RBQ/nightly/ko/guides/common/emo">비상 정지 및 복구</a> 절차를 따른 후 계속 진행하세요.</p></div></div><h2 id="관절-센서-진단" tabindex="-1">관절 &amp; 센서 진단 <a class="header-anchor" href="#관절-센서-진단" aria-label="Permalink to &quot;관절 &amp; 센서 진단&quot;">​</a></h2><p>진단 테이블에는 각 다리/관절별 값(온도, 위치 오차 등)과 IMU 측정값(자이로, 가속도)이 표시됩니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="관절 및 센서 진단 테이블" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">관절/센서 진단 테이블</figcaption></figure><h3 id="관절-명칭-규칙" tabindex="-1">관절 명칭 규칙 <a class="header-anchor" href="#관절-명칭-규칙" aria-label="Permalink to &quot;관절 명칭 규칙&quot;">​</a></h3><table tabindex="0"><thead><tr><th>약어</th><th>관절</th></tr></thead><tbody><tr><td>HRR / HRP / HRK</td><td>뒤 오른쪽 — 롤 / 피치 / 무릎</td></tr><tr><td>HLR / HLP / HLK</td><td>뒤 왼쪽 — 롤 / 피치 / 무릎</td></tr><tr><td>FRR / FRP / FRK</td><td>앞 오른쪽 — 롤 / 피치 / 무릎</td></tr><tr><td>FLR / FLP / FLK</td><td>앞 왼쪽 — 롤 / 피치 / 무릎</td></tr></tbody></table><h2 id="인식-모듈-상태" tabindex="-1">인식 모듈 상태 <a class="header-anchor" href="#인식-모듈-상태" aria-label="Permalink to &quot;인식 모듈 상태&quot;">​</a></h2><p>이 패널에는 비전 및 센서 모듈(IR 프로젝터, 야간 투시, LED, 버저 등)의 ON/OFF 상태와 동작/오류/카운트 값(Fail / Count)이 표시됩니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="인식 모듈 상태 패널" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">인식 모듈 상태</figcaption></figure><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>인식 모듈이 <strong>OFF</strong> 표시이거나 오류가 있으면 RL (Vision Trot) 모드 등 비전 기반 기능을 사용할 수 없거나 불안정할 수 있습니다.</p></div></div><h2 id="전원-스위치-모듈-점검" tabindex="-1">전원 스위치 &amp; 모듈 점검 <a class="header-anchor" href="#전원-스위치-모듈-점검" aria-label="Permalink to &quot;전원 스위치 &amp; 모듈 점검&quot;">​</a></h2><p>이 패널에는 비전 컴퓨터, 카메라, LiDAR 및 기타 주변 장치의 전원 스위치 상태와 BAT / LEGS / ADDON / EXTERN / CHARGE의 부하 측정값이 표시됩니다.</p><p><strong>Reset</strong>으로 카운터를 초기화하고 <strong>Check</strong>로 상태를 새로고침합니다.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="전원 스위치 및 모듈 상태 점검 패널" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">전원 스위치 &amp; 모듈 점검</figcaption></figure><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>로봇 상태를 확인했으면 충전하거나 보관합니다:</p><ul><li><strong><a href="/RBQ/nightly/ko/guides/common/charging.html">→ 6-1. 충전</a></strong></li><li><strong><a href="/RBQ/nightly/ko/guides/common/packing.html">→ 6-2. 포장</a></strong></li><li><strong><a href="/RBQ/nightly/ko/guides/common/emo.html">→ 6-3. 비상 정지 및 복구</a></strong></li></ul>',23)])])}const R=r(c,[["render",d]]);export{_ as __pageData,R as default};
